"""`receipt.py` is sketch_receipt.py's sketch-sha512 (`vectors.json`, generated by that file), and the receipt kernel's
index arithmetic (`fill.cu`: rstage2's swizzled staging, sgn4, rsketch's m16n8k32 fragments) restated here computes the
same σ as `receipt.sketches` over `receipt.tile_blocks`'s blocks, at both tiles."""
from __future__ import annotations

import hashlib
import json
import sys
from pathlib import Path

import numpy as np
import pytest

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE.parent))

import receipt as R  # noqa: E402

VECTORS = json.loads((HERE / "vectors.json").read_text())


def vector_blocks() -> np.ndarray:
    rng = np.random.default_rng(7)
    blocks = np.concatenate([rng.integers(0, 256, (3, R.BLOCK), dtype=np.uint8), np.full((1, R.BLOCK), 0x80, np.uint8),
                             np.full((1, R.BLOCK), 0x7F, np.uint8)])
    assert hashlib.sha256(blocks.tobytes()).hexdigest() == VECTORS["blocks_sha256"]
    return blocks


@pytest.mark.parametrize("case", VECTORS["cases"], ids=lambda c: c["seed"][:8])
def test_receipts_are_sketch_receipts(case):
    seed, blocks = bytes.fromhex(case["seed"]), vector_blocks()
    assert hashlib.sha256(R.sign_bits(seed).tobytes()).hexdigest() == case["sign_bits_sha256"]
    assert R.prefix(seed).hex() == case["prefix"]
    sk = R.sketches(R.signs(seed), blocks)
    assert sk.tolist() == case["sketches"]
    assert [y.hex() for y in R.receipts_of(seed, sk, VECTORS["j0"])] == case["receipts"]


def test_tile_blocks_and_their_indices():
    T, M, N = 64, 128, 192
    rng = np.random.default_rng(1)
    c, u = (rng.standard_normal((M, N)).astype(np.float32) for _ in range(2))
    blocks = R.tile_blocks(c, u, T, 1, 2)
    assert blocks.shape == (8, R.BLOCK)
    assert blocks[0].tobytes() == c[64:80, 128:192].astype("<f4").tobytes()
    assert blocks[4].tobytes() == u[64:80, 128:192].astype("<f4").tobytes()
    seed = bytes(range(64))
    y = R.tile_receipts(seed, R.signs(seed), c, u, T, 5, 1, 2)
    assert y == b"".join(R.receipts_of(seed, R.sketches(R.signs(seed), blocks), 40))
    tiles = [(0, 0), (1, 2)]
    fc = np.stack([c[a * T:(a + 1) * T, b * T:(b + 1) * T].ravel() for a, b in tiles]).view(np.uint32)
    fu = np.stack([u[a * T:(a + 1) * T, b * T:(b + 1) * T].ravel() for a, b in tiles]).view(np.uint32)
    every = R.all_receipts(seed, fc, fu, chunk=3)
    assert every[1].tobytes() == R.tile_receipts(seed, R.signs(seed), c.view(np.uint32), u.view(np.uint32), T, 1, 1, 2)


def test_key_head_is_sha512_after_the_prefix():
    seed = bytes(range(64))
    k = R.key(seed)
    head = [int(x) for x in k[:64].view("<u8")]
    tail = (40).to_bytes(8, "big") + bytes(range(64))
    pad = tail + b"\x80" + bytes(128 - len(tail) - 1 - 16) + (8 * (128 + len(tail))).to_bytes(16, "big")
    digest = b"".join(x.to_bytes(8, "big") for x in R.compress(head, pad))
    assert digest == hashlib.sha512(R.prefix(seed) + tail).digest()
    assert k[64:].tobytes() == R.sign_bits(seed).tobytes()


def rswz(T: int, n: int, w: int) -> int:
    return w ^ (4 * (n & 7) ^ 8 * ((w // T) & 3))


def sgn4(x: int) -> int:
    m = (x * 0x00204081) & 0x01010101
    return ((m * 0xFF) | 0x01010101) & 0xFFFFFFFF


def bytes_of(r: int) -> np.ndarray:
    return np.frombuffer(int(r).to_bytes(4, "little"), np.int8).astype(np.int64)


def kernel_sketch(st: np.ndarray, bits: np.ndarray, T: int) -> np.ndarray:
    """rsketch: 8 warps over the 128 32-byte steps, each m16n8k32 built lane by lane as the PTX fragment layout lays it."""
    RB = T * T * 4 // R.BLOCK
    NG = (RB + 7) // 8
    words = st.view("<u4")
    rows = bits.view("<u4").reshape(R.ROWS, -1)
    sig = np.zeros((RB, R.ROWS), np.int64)
    for warp in range(8):
        acc = np.zeros((NG, 16, 8), np.int64)
        for i in range(R.BLOCK // 32 // 8):
            kc = warp * 16 + i
            A = np.zeros((16, 32), np.int64)
            B = np.zeros((NG, 32, 8), np.int64)
            for lane in range(32):
                g, q = lane >> 2, lane & 3
                s0, s8 = int(rows[g][kc]), int(rows[g + 8][kc])
                a = [sgn4((s0 >> 4 * q) & 15), sgn4((s8 >> 4 * q) & 15),
                     sgn4((s0 >> (16 + 4 * q)) & 15), sgn4((s8 >> (16 + 4 * q)) & 15)]
                A[g, 4 * q:4 * q + 4] = bytes_of(a[0])
                A[g + 8, 4 * q:4 * q + 4] = bytes_of(a[1])
                A[g, 16 + 4 * q:20 + 4 * q] = bytes_of(a[2])
                A[g + 8, 16 + 4 * q:20 + 4 * q] = bytes_of(a[3])
                for ng in range(NG):
                    n = ng * 8 + g
                    if n < RB:
                        base = n * R.BLOCK // 4
                        B[ng, 4 * q:4 * q + 4, g] = bytes_of(words[base + rswz(T, n, kc * 8 + q)])
                        B[ng, 16 + 4 * q:20 + 4 * q, g] = bytes_of(words[base + rswz(T, n, kc * 8 + q + 4)])
            for ng in range(NG):
                acc[ng] += A @ B[ng]
        for ng in range(NG):
            for lane in range(32):
                g, q = lane >> 2, lane & 3
                for e in range(4):
                    n, row = ng * 8 + 2 * q + (e & 1), g + 8 * (e >> 1)
                    if n < RB:
                        sig[n, row] += acc[ng, row, 2 * q + (e & 1)]
    return sig


@pytest.mark.parametrize("T", [64, 128])
def test_kernel_layout_sketches_the_blocks(T):
    rng = np.random.default_rng(T)
    tile = rng.integers(0, 1 << 32, (T, T), dtype=np.uint64).astype("<u4").view("<f4")
    RB = T * T * 4 // R.BLOCK
    st = np.zeros(RB * R.BLOCK, np.uint8)
    words = st.view("<u4")
    flat = tile.view("<u4").ravel()
    for L in range(T * T):
        n, w = divmod(L, R.BLOCK // 4)
        words[n * R.BLOCK // 4 + rswz(T, n, w)] = flat[L]
    seed = bytes(range(64))
    want = R.sketches(R.signs(seed), tile.view(np.uint8).reshape(-1, R.BLOCK))
    assert np.array_equal(kernel_sketch(st, R.sign_bits(seed), T), want)


@pytest.mark.parametrize("T", [64, 128])
def test_swizzle_is_a_permutation_within_each_block_and_conflict_free(T):
    for n in range(T * T * 4 // R.BLOCK):
        assert sorted(rswz(T, n, w) for w in range(R.BLOCK // 4)) == list(range(R.BLOCK // 4))
    for kc in range(R.BLOCK // 32):
        for reg in (0, 4):
            banks = {rswz(T, g, kc * 8 + q + reg) % 32 for g in range(8) for q in range(4)}
            assert len(banks) == 32
